'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='stylevault.v1';let state={version:1,favorites:[],notes:{},tags:{},collections:[],members:{},custom:[],size:240},base=[],manifest,view='all',category='',collection='',selected=[];
try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved))}catch(e){$('#status').textContent='Saved data could not be read. Restore a backup.'}
function validate(d){if(!d||d.version!==1||!Array.isArray(d.favorites)||!Array.isArray(d.custom)||!Array.isArray(d.collections)||typeof d.notes!=='object'||!d.notes||typeof d.tags!=='object'||!d.tags||typeof d.members!=='object'||!d.members)throw Error('Invalid StyleVault backup');if(d.custom.length>5000||!d.custom.every(x=>typeof x.id==='string'&&x.id.startsWith('user-')&&typeof x.name==='string'&&typeof x.prompt==='string'&&typeof x.section==='string'))throw Error('Invalid custom styles');if(!d.favorites.every(x=>typeof x==='string')||!d.collections.every(x=>typeof x==='string')||!Object.values(d.notes).every(x=>typeof x==='string')||!Object.values(d.tags).every(x=>Array.isArray(x)&&x.every(t=>typeof t==='string'))||!Object.values(d.members).every(x=>Array.isArray(x)&&x.every(t=>typeof t==='string')))throw Error('Invalid personal data');return {...d,size:Math.max(180,Math.min(360,Number(d.size)||240))}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#status').textContent='Saved on this device';return true}catch(e){$('#status').textContent='Storage full or unavailable — export a backup';toast('Could not save. Export a backup now.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2400)}
const all=()=>[...base,...state.custom],get=id=>all().find(x=>x.id===id);function imageFor(s){if(s.id.startsWith('user-')){return typeof s.image==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(s.image)?s.image:''}const i=manifest.sections.krea2.images.find(i=>i.style===s.name);return i?i.file:''}
async function copy(s){try{await navigator.clipboard.writeText(s.prompt);toast('Original style description copied')}catch{toast('Clipboard unavailable. Select and copy the description.')}}
function sidebar(){let cats=[...new Set(base.map(x=>x.section))];$('#categories').innerHTML=cats.map(c=>`<button data-category="${esc(c)}" class="${category===c?'active':''}">${esc(c)} <small>(${base.filter(s=>s.section===c).length})</small></button>`).join('');$('#collections').innerHTML=state.collections.map(c=>`<button data-collection="${esc(c)}" class="${collection===c?'active':''}">${esc(c)}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&!category&&!collection))}
function filtered(){const q=$('#search').value.toLowerCase().trim();let a=all().filter(s=>(!category||s.section===category)&&(!collection||(state.members[collection]||[]).includes(s.id))&&(view!=='favorites'||state.favorites.includes(s.id))&&(view!=='custom'||s.id.startsWith('user-'))&&(!q||[s.name,s.prompt,s.section,state.notes[s.id],...(state.tags[s.id]||[])].join(' ').toLowerCase().includes(q)));if($('#sort').value==='az')a.sort((a,b)=>a.name.localeCompare(b.name));return a}
function render(){sidebar();$('#total').textContent=all().length;$('#grid').style.setProperty('--thumb',state.size+'px');$('#size').value=state.size;let a=filtered();$('#count').textContent=`${a.length} styles${category?' · '+category:''}${collection?' · '+collection:''}`;$('#grid').innerHTML=a.map(s=>`<article class="card ${selected.includes(s.id)?'selected':''}"><button class="image" data-open="${esc(s.id)}" aria-label="Preview ${esc(s.name)}">${imageFor(s)?`<img loading="lazy" src="${esc(imageFor(s))}" alt="${esc(s.name)} preview">`:'✧ Your style'}</button><div class="cardbody"><span class="category">${esc(s.section)}</span><h2>${esc(s.name)}</h2><div class="actions"><button data-copy="${esc(s.id)}">Copy style</button><button data-fav="${esc(s.id)}" aria-label="Favorite ${esc(s.name)}" aria-pressed="${state.favorites.includes(s.id)}">${state.favorites.includes(s.id)?'♥':'♡'}</button><button data-pick="${esc(s.id)}" aria-label="Compare ${esc(s.name)}" aria-pressed="${selected.includes(s.id)}">⊞</button></div></div></article>`).join('')||'<p class="empty">No styles found. Try a different search or filter.</p>';$('#comparebar').hidden=!selected.length;$('#selection').textContent=`${selected.length}/2 selected`;$('#compare').disabled=selected.length!==2}
function detail(id){let s=get(id);if(!s)return;const d=$('#detail');d.innerHTML=`<div class="dialoghead"><h2>${esc(s.name)}</h2><button data-full>Fullscreen</button><button data-copy="${esc(id)}">Copy style</button><button data-close>Close</button></div><div class="detailgrid"><div>${imageFor(s)?`<img src="${esc(imageFor(s))}" alt="${esc(s.name)}">`:''}<p class="muted">${esc(s.section)} · ${id.startsWith('user-')?'Personal style':'Original Clio preview · 512px'}</p></div><div><p class="prose">${esc(s.prompt)}</p><div class="fields"><label>Personal notes<textarea id="note">${esc(state.notes[id]||'')}</textarea></label><label>Tags (comma separated)<input id="tags" value="${esc((state.tags[id]||[]).join(', '))}"></label><label>Collections<select id="membership" multiple size="${Math.max(2,Math.min(state.collections.length,5))}">${state.collections.map(c=>`<option value="${esc(c)}" ${(state.members[c]||[]).includes(id)?'selected':''}>${esc(c)}</option>`).join('')}</select></label><p class="muted">Use Ctrl / Cmd to select multiple collections.</p>${id.startsWith('user-')?`<button id="editCustom">Edit style</button> <button id="deleteCustom">Delete style</button>`:''}</div></div></div>`;$('#note').oninput=e=>{state.notes[id]=e.target.value;save()};$('#tags').oninput=e=>{state.tags[id]=e.target.value.split(',').map(x=>x.trim()).filter(Boolean);save();render()};$('#membership').onchange=e=>{let chosen=[...e.target.selectedOptions].map(o=>o.value);state.collections.forEach(c=>{state.members[c]=(state.members[c]||[]).filter(x=>x!==id);if(chosen.includes(c))state.members[c].push(id)});save();render()};if($('#editCustom'))$('#editCustom').onclick=()=>{d.close();edit(s)};if($('#deleteCustom'))$('#deleteCustom').onclick=()=>{if(confirm('Delete this personal style?')){state.custom=state.custom.filter(x=>x.id!==id);save();d.close();render()}};if(!d.open)d.showModal()}
function edit(s){const d=$('#editor');d.innerHTML=`<div class="dialoghead"><h2>${s?'Edit':'Add'} personal style</h2><button data-close>Close</button></div><form class="fields"><label>Name<input name="name" required maxlength="180" value="${esc(s?.name||'')}"></label><label>Category<input name="section" required value="${esc(s?.section||'Personal')}"></label><label>Style description<textarea name="prompt" required>${esc(s?.prompt||'')}</textarea></label><label>Preview image (optional, up to 1 MB)<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label><button type="submit">Save style</button></form>`;d.querySelector('form').onsubmit=async e=>{e.preventDefault();let f=e.target,file=f.image.files[0],image=s?.image||'';if(file){if(file.size>1000000)return toast('Choose an image under 1 MB');image=await new Promise(r=>{let reader=new FileReader;reader.onload=()=>r(reader.result);reader.readAsDataURL(file)})}let entry={id:s?.id||'user-'+crypto.randomUUID(),name:f.elements.name.value.trim(),section:f.section.value.trim(),prompt:f.prompt.value,image};if(!entry.name||!entry.section)return;state.custom=state.custom.filter(x=>x.id!==entry.id);state.custom.push(entry);save();d.close();render()};d.showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.close!==undefined){b.closest('dialog').close();if(document.fullscreenElement)document.exitFullscreen();render()}if(d.full!==undefined)$('#detail').requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser'));if(d.open)detail(d.open);if(d.copy)copy(get(d.copy));if(d.fav){state.favorites=state.favorites.includes(d.fav)?state.favorites.filter(x=>x!==d.fav):[...state.favorites,d.fav];save();render()}if(d.pick){if(selected.includes(d.pick))selected=selected.filter(x=>x!==d.pick);else if(selected.length<2)selected.push(d.pick);else toast('Clear a selection to choose another style');render()}if(d.view){view=d.view;category='';collection='';render()}if(d.category){category=category===d.category?'':d.category;view='all';collection='';render()}if(d.collection){collection=collection===d.collection?'':d.collection;view='all';category='';render()}});
$('#search').oninput=render;$('#sort').onchange=render;$('#size').oninput=e=>{state.size=+e.target.value;save();$('#grid').style.setProperty('--thumb',state.size+'px')};$('#addStyle').onclick=()=>edit();$('#addCollection').onclick=()=>{let c=prompt('Collection name')?.trim();if(c&&!state.collections.includes(c)){state.collections.push(c);state.members[c]=[];save();render()}};$('#clear').onclick=()=>{selected=[];render()};$('#random').onclick=()=>{let a=filtered();if(a.length)detail(a[Math.floor(Math.random()*a.length)].id);else toast('No styles in this filter')};$('#compare').onclick=()=>{let d=$('#detail');d.innerHTML='<div class="dialoghead"><h2>Side by side</h2><button data-full>Fullscreen</button><button data-close>Close</button></div><div class="comparison">'+selected.map(id=>{let s=get(id);return `<section><h2>${esc(s.name)}</h2>${imageFor(s)?`<img src="${esc(imageFor(s))}" alt="${esc(s.name)}">`:''}<button data-copy="${esc(id)}">Copy style</button><p class="prose">${esc(s.prompt)}</p></section>`}).join('')+'</div>';d.showModal()};$('#backup').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='stylevault-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#restore').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>25000000)throw Error('Backup exceeds 25 MB');let restored=validate(JSON.parse(await f.text()));if(!confirm('Replace personal data on this device with this backup?'))return;state=restored;selected=[];save();render();toast('Backup restored')}catch(e){toast('Restore failed: '+e.message)}finally{$('#file').value=''}};
Promise.all([fetch('styles.json').then(r=>r.json()),fetch('manifest.json').then(r=>r.json())]).then(([s,m])=>{base=s.map((x,i)=>({...x,id:'clio-'+i}));manifest=m;render()}).catch(()=>{$('#grid').textContent='Could not load the library. Reload to try again.'});



